```python
#!/usr/bin/env python3
"""Utility for generating a changelog from a set of GitHub PRs."""

import argparse
import os
import sys

from github3 import GitHub

from qiskit_bot import __version__


class Changelog:
    """Class to generate a changelog from a list of GitHub PRs."""

    def __init__(self, repo, token, since, until, categories=None,
                 verbose=False):
        self.repo = repo
        self.token = token
        self.since = since
        self.until = until
        self.categories = categories
        self.verbose = verbose
        self.prs = []
        self.categorized = {}

    def get_prs(self):
        """Get the list of PRs from GitHub."""
        gh = GitHub(self.token)
        repo = gh.repository(*self.repo.split('/'))
        issues = repo.issues(state='closed', since=self.since)
        for pr in issues:
            if 'pull_request' not in pr.as_dict():
                continue
            if pr.closed_at is None:
                continue
            if pr.closed_at < self.since:
                continue
            if self.until and pr.closed_at > self.until:
                continue
            self.prs.append(pr)
            if self.verbose:
                print("Added PR #%s: %s" % (pr.number, pr.title))

    def categorize_prs(self):
        """Categorize the PRs by their changelog labels."""
        self.categorized = {}
        for pr in self.prs:
            labels = [x.name for x in pr.labels]
            for category in self.categories:
                if category in labels:
                    self.categorized.setdefault(category, []).append(pr)
                    break
            else:
                self.categorized.setdefault('no_changelog', []).append(pr)

    def format_markdown(self):
        """Format the changelog as a markdown string."""
        output = []
        for category in self.categories:
            if category not in self.categorized:
                continue
            output.append('## %s' % category.title())
            for pr in self.categorized[category]:
                output.append("- PR #%s: %s" % (pr.number, pr.title))
            output.append('')
        if 'no_changelog' in self.categorized:
            output.append('## No changelog entry')
            for pr in self.categorized['no_changelog']:
                output.append("- PR #%s: %s" % (pr.number, pr.title))
        return '\n'.join(output)
