class WrongNameVisitor(base.BaseVisitor):
    """Visitor that checks names inside the AST."""

    def __init__(self, *args, **kwargs) -> None:
        """Creates new visitor."""
        super().__init__(*args, **kwargs)
        self._assigned_names: List[ast.Name] = []

    def visit_Assign(self, node: ast.Assign) -> None:
        """Checks name assignment."""
        self._assigned_names.extend(
            target
            for target in node.targets
            if isinstance(target, ast.Name)
        )
        self.generic_visit(node)

    def visit_AnnAssign(self, node: ast.AnnAssign) -> None:
        """Checks name assignment."""
        if isinstance(node.target, ast.Name):
            self._assigned_names.append(node.target)
        self.generic_visit(node)

    def visit_AugAssign(self, node: ast.AugAssign) -> None:
        """Checks name assignment."""
        if isinstance(node.target, ast.Name):
            self._assigned_names.append(node.target)
        self.generic_visit(node)

    def _check_reassignment(self) -> None:
        for prev_name, next_name in zip(
            self._assigned_names, self._assigned_names[1:],
        ):
            if prev_name.id == next_name.id:
                self.add_violation(
                    violations.ReassigningVariablePresentViolation(
                        next_name,
                        next_name.id,
                    ),
                )

    def generic_visit(self, node: ast.AST) -> None:
        """Helper to preserve attribute visit order."""
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef, ast.Lambda)):
            self._check_reassignment()
            self._assigned_names = []
        super().generic_visit(node)
